package com.yisy.modules.doramcu.ai;

import com.yisy.modules.doramcu.hex.Hex3D;

/**
 * Represents an insight generated by a station's AI Core.
 * <p>
 * Insights provide information about the station's analysis of the current
 * situation, including threats detected, bonuses applied, and optimization
 * suggestions.
 * </p>
 */
public class StationAiInsight {

    /**
     * Types of insights that can be generated.
     */
    public enum InsightType {
        /** An enemy threat has been detected */
        THREAT_DETECTED,
        /** A defense bonus is being applied to stationed fleets */
        DEFENSE_BONUS,
        /** Research output has been generated */
        RESEARCH_OUTPUT,
        /** Economic optimization has been applied */
        ECONOMIC_OPTIMIZATION,
        /** Resource extraction bonus has been applied */
        RESOURCE_EXTRACTION,
        /** Production scheduling optimization */
        PRODUCTION_SCHEDULING,
        /** Colony management optimization */
        COLONY_MANAGEMENT
    }

    private final InsightType type;
    private final String description;
    private final Hex3D position;

    /**
     * Creates a new insight.
     *
     * @param type the type of insight
     * @param description a human-readable description
     * @param position the position associated with this insight, or null
     */
    public StationAiInsight(InsightType type, String description, Hex3D position) {
        if (type == null) {
            throw new IllegalArgumentException("Insight type must not be null");
        }
        if (description == null) {
            throw new IllegalArgumentException("Description must not be null");
        }
        this.type = type;
        this.description = description;
        this.position = position;
    }

    /**
     * Returns the type of this insight.
     *
     * @return the insight type
     */
    public InsightType getType() {
        return type;
    }

    /**
     * Returns the human-readable description of this insight.
     *
     * @return the description
     */
    public String getDescription() {
        return description;
    }

    /**
     * Returns the position associated with this insight.
     *
     * @return the position, or null if not applicable
     */
    public Hex3D getPosition() {
        return position;
    }

    @Override
    public String toString() {
        return String.format("StationAiInsight{type=%s, description='%s', position=%s}",
                type, description, position);
    }
}
